let assessmentYear = 12;
let assessmentTask = '1';
const assessmentLabels = {Project:'Projects',Theory:'Theory tests',Practical:'Practical tests',Examination:'Examinations'};
const assessmentEscape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function assessmentList(items) { return '<ul>'+items.map(item=>`<li>${assessmentEscape(item)}</li>`).join('')+'</ul>'; }
function assessmentSelectedYear() { return assessmentCatalogue.years.find(item=>item.year===assessmentYear); }
function assessmentGameContract(year,task){
 const e=assessmentEscape, contract=assessmentCatalogue.gameContracts.find(item=>item.year===year);
 const rows=items=>items.map(item=>`<section class="assessment-requirement"><h4>${e(item.id)}</h4><p>${e(item.text)}</p><p><strong>Acceptance:</strong> ${e(item.acceptance)}</p></section>`).join('');
 return `<section class="assessment-game-contract"><h3>One game contract, five scenario themes</h3><p>${e(contract.scope)} Every theme uses the same rules, data fixtures and 100-mark guide. Students choose the setting and presentation; they do not need extra mechanics or specialist domain knowledge.</p><p><strong>Assets:</strong> AI-generated decorative art/audio or Pygame primitives are equally acceptable. No marks for visual polish. Assessed code assistance follows the issued school conditions.</p><details><summary>Shared functional requirements (${contract.functional.length})</summary>${rows(contract.functional)}</details><details><summary>Shared non-functional requirements (${contract.nonFunctional.length})</summary>${rows(contract.nonFunctional)}</details><details><summary>Scope ceiling and preparation</summary><p>${e(contract.prerequisites)}</p>${assessmentList(contract.excluded)}<p>Workshop plan: ${e(contract.schedule[0])}.</p></details><p><a class="button" href="${e(task.gameContract)}" download>Common game requirements</a><a class="button secondary" href="${e(task.gameRubric)}" download>Common marking guide</a><a class="button secondary" href="assessments/games/year${year}-acceptance.csv" download>Common acceptance tests</a><a class="button secondary" href="assessments/games/year${year}-syllabus-map.md" download>Project syllabus map</a></p></section>`;
}

function assessmentChoices() {
  const year=assessmentSelectedYear(), e=assessmentEscape;
  const tasks=year.tasks.filter(task=>assessmentTask==='all'||String(task.number)===assessmentTask);
  return tasks.map(task=>`<section class="assessment-slot" aria-labelledby="assessment-task-${task.number}"><div class="assessment-slot-heading"><p class="eyebrow">YEAR ${year.year} · TASK ${task.number} · ${e(task.type)} · ${task.weight}% OF ANNUAL SCHOOL MARK</p><h2 id="assessment-task-${task.number}">${e(task.title)}</h2><p><strong>Local proposal:</strong> ${e(task.timing)}</p></div><p class="assessment-context-note">${task.type==='Project'?`Choose one project context, or a moderated equivalent. All choices retain the ${task.weight}% course weight. The ${task.budget} workshops include planning, implementation, feedback and testing.`:'One standard assessment for this slot. The complete paper, task-specific key and school conditions still need development.'}</p><p><strong>Content family:</strong> ${e(task.scope)}. ${task.chapters.map(id=>`<a href="#${e(id)}">${e(id.replace(/^unit\d-/, '').replace(/-/g,' '))}</a>`).join(' · ')}</p>${task.gameContract?assessmentGameContract(year.year,task):''}<div class="assessment-options">${task.options.map(option=>`<article class="assessment-option"><p class="assessment-stage">${option.pack?'Brief + unfinished starter pack':task.type==='Project'?'Draft brief + resource plan':'Question / exam blueprint'}</p><h3>${e(option.title)}</h3><p>${e(option.pitch)}</p><details><summary>Requirements, resources and evidence</summary><h4>What students produce</h4>${assessmentList(option.requirements)}${option.routes?'<h4>Delivery routes</h4>'+assessmentList(option.routes):''}<h4>Resources and setup</h4>${assessmentList(option.resources)}<h4>${task.type==='Project'?'Initial acceptance checks':'Review before issue'}</h4>${assessmentList(option.tests)}${task.type==='Project'?'<p>Suggested 100-mark framework: investigation 15, design 25, implementation 35, testing 15 and evaluation 10. Translate this into task-specific marking points before issue.</p>':''}</details><p class="assessment-downloads"><a class="button ${option.pack?'secondary':''}" href="${e(option.brief)}" download>Download ${task.type==='Project'?'editable brief':'blueprint'}</a>${option.pack?`<a class="button" href="${e(option.download)}" download>Download starter pack</a>`:''}</p></article>`).join('')}</div></section>`).join('');
}
function assessmentYearOverview() {
 const year=assessmentSelectedYear(),e=assessmentEscape;
 return `<div class="assessment-year-heading"><p class="eyebrow">YEAR ${year.year} · UNITS ${e(year.units)} · 2027 PLANNING</p><h2>One outline. Flexible projects.</h2><p>These are annual <strong>school-assessment</strong> weights across the pair of units. The external Year 12 ATAR examination is separate. Individual task splits below follow the sample structure; local dates follow our teaching sequence.</p></div><table class="assessment-weights"><caption>Year ${year.year} assessment type totals</caption><thead><tr><th scope="col">Assessment type</th><th scope="col">Required total</th><th scope="col">Proposed task split</th></tr></thead><tbody>${Object.entries(year.weights).map(([type,weight])=>`<tr><th scope="row">${assessmentLabels[type]}</th><td><strong>${weight}%</strong></td><td>${year.tasks.filter(t=>t.type===type).map(t=>`T${t.number}: ${t.weight}%`).join(' + ')}</td></tr>`).join('')}</tbody></table><details class="assessment-schedule"><summary>View the eight-task schedule</summary><ol class="assessment-timeline" aria-label="Year ${year.year} proposed assessment outline">${year.tasks.map(task=>`<li><button type="button" class="assessment-task-link secondary" data-assessment-task="${task.number}" aria-pressed="${assessmentTask===String(task.number)}"><span class="assessment-task-title">Task ${task.number} · ${e(task.title)}</span><span>${e(task.type)} · ${task.weight}% · ${task.type==='Project'?task.options.length+' project choices':'Standard task'}</span></button><p>${e(task.timing)}</p><details class="assessment-sample"><summary>SCSA sample timing for comparison</summary><p>${e(task.sampleTiming)}. Reference only: our local proposal moves this task to follow taught prerequisites and the textbook’s allocated workshops. Confirm actual school dates before issue.</p></details></li>`).join('')}</ol></details><div class="assessment-filter"><label for="assessment-task-select">Browse an assessment slot</label><select id="assessment-task-select">${year.tasks.map(t=>`<option value="${t.number}" ${assessmentTask===String(t.number)?'selected':''}>Task ${t.number} · ${e(t.title)} · ${t.weight}%</option>`).join('')}<option value="all" ${assessmentTask==='all'?'selected':''}>All eight tasks</option></select></div><p id="assessment-status" role="status">${assessmentStatus()}</p><div id="assessment-options-region">${assessmentChoices()}</div>`;
}
function assessmentStatus(){const y=assessmentSelectedYear(),tasks=y.tasks.filter(t=>assessmentTask==='all'||String(t.number)===assessmentTask);const projects=tasks.filter(t=>t.type==='Project').reduce((n,t)=>n+t.options.length,0),standard=tasks.filter(t=>t.type!=='Project').length;return `Year ${y.year}: ${assessmentTask==='all'?'all eight tasks':'Task '+assessmentTask}. ${[projects?projects+' project choices':'',standard?standard+' standard assessment '+(standard===1?'blueprint':'blueprints'):''].filter(Boolean).join(' and ')}. Choice applies to projects only.`;}
function assessmentHubPage(){
 const s=assessmentCatalogue.sources;
 return `<article class="assessment-hub"><p class="eyebrow">TEACHER RESOURCE · 2027 · UNITS 1–4</p><h1>Assessments.<br>Projects with choice.</h1><p class="lede">Choose a meaningful problem, see the evidence it can assess, and plan the resources before issuing the task.</p><nav class="assessment-jump" aria-label="Assessment sections"><a href="#assessments/heading-course-outlines-and-task-options">Project choices &amp; standard tasks</a><a href="#assessments/heading-game-scope-and-asset-choices">Game scope &amp; assets</a><a href="#assessments/heading-downloads-and-editable-templates">Downloads</a><a href="#assessments/heading-sources-and-release-review">Sources &amp; release review</a></nav><div class="notice"><strong>Original planning drafts, not SCSA-approved assessments.</strong> This collection contains 18 alternative project briefs, eight standard controlled-test blueprints and four standard exam blueprints. All ten Pygame game themes and two database options include starter packs and synthetic data. Programming projects were scope-audited on 26 October 2026. Full controlled papers, private keys and final school release decisions remain to be developed. Everything on this public site is visible to students.</div><details class="assessment-guidance"><summary>What is required, and what can teachers choose?</summary><p>The prescribed type totals come from the syllabuses. The eight numbered slots, individual task splits and sample dates are a useful model, not a requirement to teach the same project. Both syllabuses limit summative tasks to eight, each at least 5%, with all assessment types represented and a representative content sample.</p><p>Our dates use four lessons per week, 16 teaching weeks and Weeks 17–18 for exams. Year 11 programming uses 10 existing workshops; Year 11 databases 14; Year 12 programming 12; Year 12 databases 16 plus four foundation lessons. Tests replace an existing activity rather than add periods. Confirm school dates, period length and taught prerequisites.</p><p>Task 1 now requires a bounded Pygame game. This is our chosen teaching context, not an SCSA GUI requirement. All game themes in each year use one common contract and guide. Primitive artwork can earn full marks; headsets are unnecessary. Publish the final criteria, permitted assistance/AI, individual-authorship process and access arrangements. Version records, supervised milestones and a short explanation/change demonstration authenticate the existing project rather than create extra weighted tasks.</p><p><a href="assessments/coverage-and-release.md" download>Content allocation and source review</a> <a href="assessments/teacher-release-checklist.md" download>Teacher release checklist</a></p></details><h2>Course outlines and task options</h2><div class="assessment-year-filter"><label for="assessment-year-select">Teaching year level</label><select id="assessment-year-select"><option value="11" ${assessmentYear===11?'selected':''}>Year 11 · Units 1–2</option><option value="12" ${assessmentYear===12?'selected':''}>Year 12 · Units 3–4</option></select><span>Target teaching year: <strong>2027</strong></span></div><div id="assessment-year-region">${assessmentYearOverview()}</div><section class="assessment-quest"><p class="eyebrow">GAME SCOPE · YEAR-LEVEL PROGRESSION</p><h2>Game scope and asset choices</h2><p><strong>Year 11:</strong> one small arena, functions, one-dimensional lists, basic collisions, scoring and score-file processing.</p><p><strong>Year 12:</strong> two small tile maps, a student-authored actor hierarchy, dictionaries and bounded algorithm/reporting work. No advanced physics, pathfinding, networking or VR is required.</p><p>The five themes change labels and presentation, while preserving rules, tests and marks. AI-generated decorative assets and Pygame primitives are equally acceptable. Artwork, animation and sound production do not earn extra marks; keep a shapes/text fallback.</p><p><a class="button" href="assessments/games/scope-audit-2027.md" download>Programming-project scope audit</a><a class="button secondary" href="assessments/games/asset-policy.md" download>AI and primitive asset policy</a><a class="button secondary" href="assessments/games/asset-log.csv" download>Asset and AI-source log</a></p><p>Textbook examples and project-workshop slides use ungraded practice contexts. The selected assessment game contract defines the Task 1 requirements. Database projects retain their own relational design and SQL evidence.</p></section><section class="card"><p class="eyebrow">BEFORE PROJECT ISSUE · A03</p><h2>Trial the workload and agree the marking</h2><p>Use the trial pack to record the complete Year 11/12 core, actual workshop time, support and two-teacher moderation. Candidate marking anchors preserve the existing totals; live trial results and independent approval remain pending.</p><p><a class="button" href="project-trial/">Open the trial and moderation pack</a><a class="button secondary" href="project-trial/project-trial-moderation-pack.zip" download>Download editable records</a></p></section><h2>Downloads and editable templates</h2><p>Markdown files open in any text editor and can be copied into Word or an LMS. CSV files open in a spreadsheet. Starter Python and SQL files deliberately leave core implementation unfinished.</p><p><a class="button" href="assessments/assessment-planning-2027.zip" download>Download the planning collection</a> <a class="button secondary" href="assessments/assessment-outline-2027.csv" download>Editable assessment outline</a></p><ul class="assessment-template-list"><li><a href="assessments/student-workbook.md" download>Student project workbook</a></li><li><a href="assessments/project-rubric.md" download>100-mark project criteria framework</a></li><li><a href="assessments/test-record.csv" download>Expected / actual test record</a></li><li><a href="assessments/source-log.csv" download>Source and assistance log</a></li><li><a href="assessments/question-blueprint.csv" download>Question and marking-key planning grid</a></li><li><a href="assessments/exam-blueprint.csv" download>Examination section blueprint</a></li><li><a href="assessments/teacher-release-checklist.md" download>Teacher release and moderation record</a></li></ul><h2>Sources and release review</h2><p>Programming-project audit updated 26 October 2026; other assessment source review remains dated 15 October 2026. Year 12 uses the syllabus explicitly for teaching from 2027. The course page currently lists the Year 11 syllabus effective from 2026. The WACE Manual currently linked is the 2026 edition; check the 2027 manual and any later syllabus updates before issuing tasks.</p><ul><li><a href="${s.y12}">SCSA Year 12 syllabus for 2027</a>: assessment, printed pp. 21–23; examination design, p. 25.</li><li><a href="${s.y11}">SCSA current Year 11 syllabus</a>: assessment, printed pp. 20–22.</li><li><a href="${s.sample12}">SCSA Year 12 sample outline</a> and <a href="${s.sample11}">Year 11 sample outline</a>: sample task splits and reference dates.</li><li><a href="${s.manual}">WACE Manual</a> and <a href="${s.policy}">school-based assessment guidance</a>: school policy, authentication and moderation.</li><li><a href="${s.course}">Current SCSA Computer Science course page</a>: check document currency before release.</li><li><a href="${s.pygame}">Pygame documentation</a>: chosen game library for Task 1.</li></ul><p>The downloadable content allocation is a family-level map. Exact syllabus bullet-to-item mapping, task-specific marking keys, timing trials, independent moderation and school release review remain open. Official documents and third-party tools retain their own terms. Original briefs are open resources under this site’s licences.</p><p><a href="#teaching">Return to the teaching sequence</a></p></article>`;
}
function refreshAssessmentChoices(moveFocus=false){
 document.getElementById('assessment-options-region').innerHTML=assessmentChoices();
 document.getElementById('assessment-task-select').value=assessmentTask;
 document.getElementById('assessment-status').textContent=assessmentStatus();
 document.querySelectorAll('[data-assessment-task]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.assessmentTask===assessmentTask)));
 prepareContentScrollAreas();prepareActionButtons();
 if(moveFocus){const heading=document.querySelector('#assessment-options-region h2');heading.tabIndex=-1;heading.focus();heading.scrollIntoView({block:'start'});}
}
document.addEventListener('change',event=>{
 if(event.target.id==='assessment-year-select'){
  assessmentYear=Number(event.target.value);assessmentTask='1';
  document.getElementById('assessment-year-region').innerHTML=assessmentYearOverview();
  prepareContentScrollAreas();prepareActionButtons();
 }else if(event.target.id==='assessment-task-select'){assessmentTask=event.target.value;refreshAssessmentChoices();}
});
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-assessment-task]');
 if(button){assessmentTask=button.dataset.assessmentTask;refreshAssessmentChoices(true);}
});
